def has_close_elements(numbers: list[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False
    # Quick check: if threshold is zero or negative, no two distinct numbers can be closer
    if threshold <= 0:
        return any(a == b for i, a in enumerate(numbers) for b in numbers[i + 1:])
    nums = sorted(numbers)
    for i in range(len(nums) - 1):
        if nums[i + 1] - nums[i] < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove all spaces
    s = paren_string.replace(' ', '')
    groups = []
    depth = 0
    start = 0
    for i, ch in enumerate(s):
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                groups.append(s[start:i+1])
    return groups

