        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v
    INF = -10**15
    dp_prev = [[INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]
    for k in range(3, 2 * N + 1):
        dp_cur = [[INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF
                # transitions from previous step
                for di1 in (0, 1):  # 0: from up (i1-1), 1: from left (i1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best:
