                if best == INF:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur
    return dp_prev[N][N] if dp_prev[N][N] != INF else 0

