def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # dp[i1][i2] = max sum at current step where path1 at (i1, j1), path2 at (i2, j2)
    prev = [[float('-inf')] * (N + 1) for _ in range(N + 1)]
    # step t = i1 + j1 = i2 + j2
    # start at (1,1) each path
    prev[1][1] = grid[1][1]
    for t in range(3, 2 * N + 1):  # since at t=2 we already processed (1,1)
        cur = [[float('-inf')] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range from max(1, t-N) to min(N, t-1)
        i_min = 1 if t - N < 1 else t - N
        i_max = N if t - 1 > N else t - 1
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if not (1 <= j1 <= N):
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if not (1 <= j2 <= N):
                    continue
                best_prev = float('-inf')
                # possible previous moves: up or left for each path
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1 or pi1 > N:
                        continue
                    pj1 = (t - 1) - pi1
                    if pj1 < 1 or pj1 > N:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1 or pi2 > N:
                            continue
                        pj2 = (t - 1) - pi2
                        if pj2 < 1 or pj2 > N:
                            continue
                        val = prev[pi1][pi2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == float('-inf'):
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                cur[i1][i2] = best_prev + add
        prev = cur
    return prev[N][N] if prev[N][N] != float('-inf') else 0

def find_number_combinations():
    digits = '123456789'
    combos = []
    for length in range(1, 10):
        for perm in __import__('itertools').permutations(digits, length):
            a = int(''.join(perm))
            b = a * 2
            c = a * 3
            sb, sc = str(b), str(c)
            if all(d in digits for d in sb) and len(set(sb)) == len(sb):
                if all(d in digits for d in sc) and len(set(sc)) == len(sc):
                    combos.append((a, b, c))
    return sorted(combos)

