def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N == 0:
        return 0
    # Ensure consistency of N
    if len(num_str) != N:
        raise ValueError("N does not match the length of num_str")
    # maximum cuts cannot exceed N-1
    if K > N - 1:
        return 0
    # dp[i][k] = maximum product for the first i digits with k multiplication signs inserted
    dp = [[-1] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # empty product
    # base case: no cuts
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])
    # DP for cuts >= 1
    for cuts in range(1, K + 1):
        # at least cuts+1 digits are needed to place cuts
        for i in range(cuts + 1, N + 1):
            best = -1
            # j is the start index of the last part (0‑based)
            # previous part ends at j, leaving j digits for the previous cuts
            for j in range(cuts, i):
                part_val = int(num_str[j:i])
                prev_val = dp[j][cuts - 1]
                if prev_val != -1:
                    prod = prev_val * part_val
                    if prod > best:
                        best = prod
            dp[i][cuts] = best
    return dp[N][K] if dp[N][K] != -1 else 0

