def verify_isbn(isbn: str) -> str:
    # Remove hyphens and parse digits
    groups = isbn.split('-')
    digits = []
    for ch in isbn.replace('-', ''):
        if ch.upper() == 'X':
            digits.append(10)
        else:
            digits.append(int(ch))
    # Compute checksum
    total = sum((i + 1) * digits[i] for i in range(10))
    if total % 11 == 0:
        return "Right"
    # Compute correct checksum digit
    s = sum((i + 1) * digits[i] for i in range(9))  # sum without last digit
    correct_digit = s % 11
    corrected_char = 'X' if correct_digit == 10 else str(correct_digit)
    # Reconstruct ISBN with corrected last digit
    new_groups = groups[:-1] + [corrected_char]
    return '-'.join(new_groups)

def verify_isbn(isbn: str) -> str:
    # Remove hyphens and validate length
    pure = isbn.replace('-', '')
    if len(pure) != 10:
        raise ValueError("ISBN must contain 10 characters excluding hyphens")
    # Compute checksum
    try:
        digits = [int(ch) for ch in pure[:-1]]
    except ValueError:
        raise ValueError("ISBN contains invalid characters")
    # Handle last character
    last_char = pure[-1]
    if last_char == 'X':
        last_val = 10
    else:
        if not last_char.isdigit():
            raise ValueError("ISBN checksum character invalid")
        last_val = int(last_char)
    digits.append(last_val)
    checksum = sum((i + 1) * d for i, d in enumerate(digits))
    if checksum % 11 == 0:
        return "Right"
    # Find correct checksum digit
    correct_digit = None
    for d in range(11):
        prod = sum((i + 1) * (digits[i] if i < 9 else d) for i in range(10))
        if prod % 11 == 0:
            correct_digit = d
            break
    if correct_digit is None:
        raise ValueError("Cannot correct ISBN")
    # Build corrected ISBN preserving hyphens
    parts = isbn.split('-')
    parts[-1] = 'X' if correct_digit == 10 else str(correct_digit)
    return '-'.join(parts)

def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1
    prev = [0] * n
    prev[0] = 1
    for _ in range(m):
        cur = [0] * n
        for pos in range(n):
            left = (pos - 1) % n
            right = (pos + 1) % n
            cur[pos] = prev[left] + prev[right]
        prev = cur
    return prev[0]

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    prev = [0] * n
    prev[0] = 1
    curr = [0] * n
    for _ in range(m):
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            curr[i] = prev[left] + prev[right]
        prev, curr = curr, prev
    return prev[0]

