    sorted_app = sorted(applicants, key=lambda x: (-x[1], x[0]))
    # Number of interview slots (150% of planned recruits, rounded down)
    k = int(m * 1.5)
    # Determine cutoff score
    if k <= 0:
        # No interview slots, no one qualifies
        return (0, [])
    if k > len(sorted_app):
        cutoff = sorted_app[-1][1]
    else:
        cutoff = sorted_app[k - 1][1]
    # All applicants with score >= cutoff qualify
    qualified = [app for app in sorted_app if app[1] >= cutoff]
    return (cutoff, qualified)

