    cutoff_index = int(1.5 * m)
    if cutoff_index <= 0:
        cutoff_score = 0
    else:
        pos = min(cutoff_index - 1, len(sorted_applicants) - 1)
        cutoff_score = sorted_applicants[pos][1]
    qualified = [(reg, score) for reg, score in sorted_applicants if score >= cutoff_score]
    return cutoff_score, qualified

