    # If lengths of encoded and original differ, mapping is impossible
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}

    # Build the mapping from encoded to original, checking for contradictions
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            if o_char in reverse:
                # Ensure one-to-one mapping
                return "Failed"
            mapping[e_char] = o_char
            reverse[o_char] = e_char

    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) < 26:
        return "Failed"

    # Decode the message using the established mapping
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

