def largest_prime_factor(n: int) -> int:
    """Return the larger prime factor of a number that is the product of two distinct primes."""
    if n <= 1:
        raise ValueError("n must be greater than 1")

    # Check if 2 is a factor
    if n % 2 == 0:
        return n // 2

    # Check odd factors up to sqrt(n)
    i = 3
    limit = int(n**0.5) + 1
    while i <= limit:
        if n % i == 0:
            return n // i
        i += 2

    # n is prime if no factors found
    return n

