def count_partitions(n: int, k: int, x: int) -> int:
    if k <= 0:
        return 1 if n == 0 else 0
    required = k * x
    if n < required:
        return 0
    m = n - required
    dp = [0] * (m + 1)
    dp[0] = 1
    for part in range(1, k + 1):
        for i in range(part, m + 1):
            dp[i] += dp[i - part]
    return dp[m]

def count_partitions(n: int, k: int, x: int) -> int:
    # Minimum sum required
    min_sum = k * x
    if n < min_sum:
        return 0
    if n == min_sum:
        return 1
    # Reduce the problem to partitions of S = n - k*x with parts <= k
    S = n - min_sum
    # DP table where dp[i][j] is number of partitions of i using parts <= j
    # Initialize dp[0][*] = 1 (one way to partition 0: use no parts)
    dp = [[0] * (k + 1) for _ in range(S + 1)]
    for j in range(k + 1):
        dp[0][j] = 1
    # Fill DP
    for i in range(1, S + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[S][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    total = 1  # sequence that ends at 'last' without appending more numbers
    max_next = last // 2
    for k in range(1, max_next + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

