def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ''
    index_map = {c: i for i, c in enumerate(inorder)}
    def recurse(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right:
            return ''
        root = postorder[post_right]
        idx = index_map[root]
        left_count = idx - in_left
        left_pre = recurse(in_left, idx - 1, post_left, post_left + left_count - 1)
        right_pre = recurse(idx + 1, in_right, post_left + left_count, post_right - 1)
        return root + left_pre + right_pre
    return recurse(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    def _build(inord: str, postord: str) -> str:
        if not inord:
            return ''
        root = postord[-1]
        idx = inord.index(root)
        left_in = inord[:idx]
        right_in = inord[idx+1:]
        left_post = postord[:len(left_in)]
        right_post = postord[len(left_in):-1]
        return root + _build(left_in, left_post) + _build(right_in, right_post)

    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder lengths must be equal")
    return _build(inorder, postorder)

