            # determine the claimed guilt status
            if "not guilty" in stmt_lower:
                claimed_guilt = False
            elif "guilty" in stmt_lower:
                claimed_guilt = True
            else:
                # statement not about guilt; ignore it
                continue
            # calculate truthfulness of the statement
            actual_guilt = (subject == scenario)
            truth = (claimed_guilt == actual_guilt)
            # consistency check
            if speaker in liar_count:
                if truth:
                    return False  # liars cannot tell the truth
            else:
                if not truth:
                    return False  # truth-tellers cannot lie
    return True

