def remaining_trees_after_clearing(l: int, areas: list) -> int:
    if not areas:
        return l
    # Normalize intervals as [start, end) assuming inclusive start, exclusive end
    merged = []
    for start, end in sorted(areas, key=lambda x: x[0]):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    cleared = sum(end - start for start, end in merged)
    remaining = max(l - cleared, 0)
    return remaining

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0
    # Clamp intervals to the road bounds and ignore empty ones
    valid = []
    for start, end in areas:
        start = max(0, min(l, start))
        end = max(0, min(l, end))
        if start < end:
            valid.append((start, end))
    if not valid:
        return l
    # Sort by start coordinate
    valid.sort(key=lambda x: x[0])
    total_removed = 0
    cur_start, cur_end = None, None
    for s, e in valid:
        if cur_start is None:
            cur_start, cur_end = s, e
        elif s <= cur_end:  # overlap (adjacent intervals are harmlessly merged)
            cur_end = max(cur_end, e)
        else:
            total_removed += cur_end - cur_start
            cur_start, cur_end = s, e
    # add the last merged interval
    total_removed += cur_end - cur_start
    remaining = l - total_removed
    return remaining if remaining > 0 else 0

def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for cost, val in herbs:
        if cost > T:
            continue
        for t in range(T, cost - 1, -1):
            nv = dp[t - cost] + val
            if nv > dp[t]:
                dp[t] = nv
    return max(dp)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        for t in range(T, time - 1, -1):
            if dp[t - time] + value > dp[t]:
                dp[t] = dp[t - time] + value
    return dp[T]

def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for t_cost, value in herbs:
        if t_cost > T:
            continue
        for time in range(T, t_cost - 1, -1):
            new_val = dp[time - t_cost] + value
            if new_val > dp[time]:
                dp[time] = new_val
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Use only the first n volumes just in case the list is longer
    volumes = volumes[:n]
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    # Find the largest capacity that can be reached
    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break
    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # DP array to keep track of achievable volumes
    dp = [False] * (V + 1)
    dp[0] = True
    # Use only the first n items (in case n < len(volumes))
    for i in range(n):
        vol = volumes[i]
        # Skip items that are larger than the box capacity
        if vol > V:
            continue
        # Update DP array from high to low to avoid reuse within the same iteration
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True
    # Find the largest achievable volume that does not exceed the capacity
    for best in range(V, -1, -1):
        if dp[best]:
            break
    return V - best

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes[:n]:
        if vol > V:
            continue
        for w in range(V, vol - 1, -1):
            if dp[w - vol]:
                dp[w] = True
    max_filled = next((w for w in range(V, -1, -1) if dp[w]), 0)
    return V - max_filled

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
