    for vol in volumes[:n]:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    max_used = max(i for i, possible in enumerate(dp) if possible)
    return V - max_used

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    prev = [0] * (m + 1)
    prev[0] = 1
    for i in range(n):
        bound = a[i]
        prefix = [0] * (m + 1)
        prefix[0] = prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + prev[j]) % MOD
        curr = [0] * (m + 1)
        for j in range(m + 1):
            if j <= bound:
                curr[j] = prefix[j]
            else:
                curr[j] = (prefix[j] - prefix[j - bound - 1]) % MOD
        prev = curr
    return prev[m] % MOD

def calculate_arrangements(n, m, a) -> int:
    mod = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        pref = [0] * (m + 1)
        pref[0] = dp[0]
        for i in range(1, m + 1):
            pref[i] = (pref[i-1] + dp[i]) % mod
        newdp = [0] * (m + 1)
        for j in range(m + 1):
            low = j - limit - 1
            if low >= 0:
                newdp[j] = (pref[j] - pref[low]) % mod
            else:
                newdp[j] = pref[j]
        dp = newdp
    return dp[m] % mod

def calculate_arrangements(n, m, a) -> int:
    mod = 10**6 + 7
    dp = [1] + [0] * m
    for limit in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0] % mod
        for t in range(1, m + 1):
            prefix[t] = (prefix[t - 1] + dp[t]) % mod
        new_dp = [0] * (m + 1)
        for t in range(m + 1):
            low = t - limit - 1
            if low >= 0:
                val = prefix[t] - prefix[low]
            else:
                val = prefix[t]
            new_dp[t] = val % mod
        dp = new_dp
    return dp[m] % mod

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    result = []
    key_len = len(key)
    key_index = 0
    for c in ciphertext:
        if c.isalpha():
            k = key[key_index % key_len]
            shift = ord(k.upper()) - ord('A')
            if c.isupper():
                base = ord('A')
                p = chr((ord(c) - base - shift) % 26 + base)
            else:
                base = ord('a')
                p = chr((ord(c) - base - shift) % 26 + base)
            result.append(p)
            key_index += 1
        else:
            result.append(c)
    return ''.join(result)

def mod_inverse(a, b):
    # Extended Euclidean Algorithm to find integers x, y such that a*x + b*y = gcd(a, b)
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        # Update x and y using the results from recursion
        return g, y1, x1 - (x // y) * y1

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None  # Inverse does not exist if a and b are not coprime
    return x % b  # Ensure the inverse is positive modulo b

def mod_inverse(a, b):
    """Return the modular inverse of a modulo b, or None if it does not exist."""
    if b == 0:
        return None
    a %= b
    if a == 0:
        return None

    t, newt = 0, 1
    r, newr = b, a
    while newr != 0:
        q = r // newr
        t, newt = newt, t - q * newt
        r, newr = newr, r - q * newr

    if r != 1:
        return None
    return t % b

