def min_groups(w, n, prices):
    prices.sort()
    i, j, groups = 0, len(prices) - 1, 0
    while i <= j:
        if prices[i] + prices[j] <= w:
            i += 1
        j -= 1
        groups += 1
    return groups

def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, len(prices) - 1
    groups = 0
    while i <= j:
        if i == j:
            groups += 1
            break
        if prices[i] + prices[j] <= w:
            i += 1
            j -= 1
        else:
            j -= 1
        groups += 1
    return groups

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new = butts // k
        total += new
        butts = new + (butts % k)
    return total
